{"function": "Describe bus", "situation": "Complaining about the bus", "cue": "Tell your friend the bus is not good.", "text": "รถเมล์ไม่ดีเลยค่ะ", "english": "The bus is not good at all.", "speaker": "female"},
{"function": "Suggest transport", "situation": "Suggesting taking the bus", "cue": "Suggest going by bus.", "text": "เราไปรถเมล์กันไหม", "english": "Shall we go by bus?", "speaker": "either"},
{"function": "Ask about bus", "situation": "Asking if the bus is here", "cue": "Ask if the bus has arrived.", "text": "รถเมล์มาหรือยังคะ", "english": "Has the bus arrived yet?", "speaker": "female"},
{"function": "Describe bus condition", "situation": "Describing the bus", "cue": "Say the bus is very crowded.", "text": "รถเมล์คนเยอะจัง", "english": "The bus is so crowded.", "speaker": "either"},
{"function": "Ask about bus", "situation": "Asking about bus number", "cue": "Ask your friend what bus number it is.", "text": "รถเมล์หมายเลขอะไรคะ", "english": "What bus number is it?", "speaker": "female"}
]}

{"teachable": true, "reason": "", "candidates": [
{"function": "Asking about story", "situation": "Friend starts talking animatedly", "cue": "Ask your friend what story they are telling.", "text": "คุณ กำลัง เล่า อะไร ครับ", "english": "What are you telling?", "speaker": "male"},
{"function": "Recounting an event", "situation": "Friend asks what you did last night", "cue": "Tell your friend you watched a movie.", "text": "ผม ดู หนัง ครับ", "english": "I watched a movie.", "speaker": "male"},
{"function": "Describing a place", "situation": "Friend asks about a trip", "cue": "Tell your friend the route was winding.", "text": "เส้นทาง คดเคี้ยว ครับ", "english": "The route was winding.", "speaker": "male"},
{"function": "Offering to tell", "situation": "Friend seems curious about something", "cue": "Offer to tell your friend the story.", "text": "ฉัน เล่า ให้ ฟัง ไหม", "english": "Shall I tell you the story?", "speaker": "female"},
{"function": "Asking for details", "situation": "Friend mentions something interesting", "cue": "Ask your friend to tell you how it happened.", "text": "คุณ เล่า ได้ ไหม", "english": "Can you tell (me)?", "speaker": "male"},
{"function": "Explaining a reason", "situation": "Friend asks why you are late", "cue": "Tell your friend the traffic was bad.", "text": "รถติด ครับ", "english": "The traffic was bad.", "speaker": "male"}
]}

